import React, { createContext, useState, useCallback, useContext, ReactNode } from 'react';
import { GoogleGenAI, GenerateContentResponse } from "@google/genai"; // Correct import
import type { GeminiContextType, GroundingChunk } from '../types';

// Ensure API_KEY is available in the environment
// IMPORTANT: The user must ensure process.env.API_KEY is set in their build/runtime environment.
// This code assumes it's available.
const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  console.error("Gemini API Key not found. Please set the API_KEY environment variable.");
  // Potentially throw an error or provide a non-functional context if critical
}

const GeminiContext = createContext<GeminiContextType | undefined>(undefined);

export const GeminiProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [lastGeminiResponseText, setLastGeminiResponseText] = useState<string | null>(null);

  const ai = API_KEY ? new GoogleGenAI({ apiKey: API_KEY }) : null;

  const invokeGemini = useCallback(async (prompt: string, systemInstruction?: string, useSearchGrounding: boolean = false): Promise<{text: string | null, groundingChunks: GroundingChunk[] | null} | null> => {
    if (!ai) {
      const noApiKeyError = new Error("Gemini API client not initialized. API Key might be missing.");
      setError(noApiKeyError);
      console.error(noApiKeyError.message);
      return null;
    }

    setIsGenerating(true);
    setError(null);
    setLastGeminiResponseText(null);

    try {
      const modelConfig: any = {
        // UPGRADED: Using gemini-3-pro-preview as the backing engine for Gemma 3 integration
        model: 'gemini-3-pro-preview',
        contents: prompt,
      };

      modelConfig.config = {
        // ENHANCED: Enabled thinking config for Gemma 3 series reasoning capabilities
        thinkingConfig: { thinkingBudget: 16384 }
      };

      if (systemInstruction || useSearchGrounding) {
        if (systemInstruction) {
          modelConfig.config.systemInstruction = systemInstruction;
        }
        if (useSearchGrounding) {
          modelConfig.config.tools = [{googleSearch: {}}];
          // IMPORTANT: Do NOT set responseMimeType: "application/json" when using googleSearch tool.
        }
      }

      const response: GenerateContentResponse = await ai.models.generateContent(modelConfig);

      const text = response.text; 
      setLastGeminiResponseText(text);
      setIsGenerating(false);

      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks as GroundingChunk[] | undefined || null;

      return { text, groundingChunks };
    } catch (e) {
      const err = e instanceof Error ? e : new Error('An unknown error occurred while calling Gemini API');
      console.error("Error invoking Gemini API:", err);
      setError(err);
      setIsGenerating(false);
      return null;
    }
  }, [ai]);

  return (
    <GeminiContext.Provider value={{ isGenerating, error, lastGeminiResponseText, invokeGemini }}>
      {children}
    </GeminiContext.Provider>
  );
};

export const useGemini = (): GeminiContextType => {
  const context = useContext(GeminiContext);
  if (context === undefined) {
    throw new Error('useGemini must be used within a GeminiProvider');
  }
  return context;
};

